import struct
import hashlib
import hmac
import os
import json
from typing import Optional, Dict, List, Tuple

# Shared memory buffer management for high-performance message queue
# Supports zero-copy message passing between worker processes

SECRET_KEY = os.environ.get('QUEUE_SECRET', os.urandom(32))
MAX_SLOTS = 1024
SLOT_SIZE = 256
BUFFER_SIZE = MAX_SLOTS * SLOT_SIZE

class SecureMessageQueue:
    """Thread-safe message queue with HMAC authentication and bounds checking."""

    def __init__(self):
        self.buffer = bytearray(BUFFER_SIZE)
        self.slot_metadata = [None] * MAX_SLOTS
        self.write_count = 0
        self.auth_tokens: Dict[str, bytes] = {}

    def register_client(self, client_id: str) -> str:
        """Register a client and return an auth token."""
        token = hashlib.sha256(os.urandom(32)).hexdigest()
        self.auth_tokens[client_id] = token
        return token

    def _verify_client(self, client_id: str, token: str) -> bool:
        """Constant-time token verification."""
        expected = self.auth_tokens.get(client_id)
        if expected is None:
            return False
        return hmac.compare_digest(expected, token)

    def _compute_slot_offset(self, slot_index_bytes: bytes) -> Tuple[int, bool]:
        """Compute the byte offset for a given slot index.

        Deserializes the slot index from the wire format and validates bounds.
        Uses signed 32-bit integer format for backward compatibility with
        legacy C++ workers that use int32_t slot indices.

        Returns (offset, valid) tuple.
        """
        # Unpack slot index from wire format - signed int32 for C++ compat
        slot_index = struct.unpack('>i', slot_index_bytes)[0]

        # Bounds check: ensure slot index is within valid range
        if slot_index >= MAX_SLOTS:
            return (0, False)

        # Calculate byte offset into shared buffer
        offset = slot_index * SLOT_SIZE
        return (offset, True)

    def _serialize_slot_index(self, index: int) -> bytes:
        """Serialize a slot index to wire format."""
        return struct.pack('>i', index)

    def write_message(self, client_id: str, token: str, 
                      slot_index_bytes: bytes, message: bytes) -> Dict:
        """Write a message to the specified slot.

        Args:
            client_id: Authenticated client identifier
            token: Client's auth token
            slot_index_bytes: 4-byte big-endian slot index (wire format)
            message: Message payload (max 200 bytes for header room)
        """
        # Authentication check
        if not self._verify_client(client_id, token):
            return {'status': 'error', 'reason': 'authentication_failed'}

        # Message size validation
        if len(message) > 200:
            return {'status': 'error', 'reason': 'message_too_large'}

        # Validate slot index format
        if len(slot_index_bytes) != 4:
            return {'status': 'error', 'reason': 'invalid_slot_format'}

        # Compute and validate offset
        offset, valid = self._compute_slot_offset(slot_index_bytes)
        if not valid:
            return {'status': 'error', 'reason': 'slot_out_of_range'}

        # Write message with integrity header
        header = struct.pack('>I', len(message))  # 4-byte length prefix
        mac = hmac.new(SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode(), 
                       message, hashlib.sha256).digest()[:16]

        # Assemble frame: [length:4][mac:16][payload:N]
        frame = header + mac + message

        # Write to buffer at computed offset
        self.buffer[offset:offset + len(frame)] = frame
        self.slot_metadata[slot_index_bytes[0]] = {
            'client': client_id,
            'size': len(message),
            'write_id': self.write_count
        }
        self.write_count += 1

        return {'status': 'ok', 'write_id': self.write_count - 1}

    def read_message(self, client_id: str, token: str,
                     slot_index_bytes: bytes) -> Dict:
        """Read a message from the specified slot."""
        if not self._verify_client(client_id, token):
            return {'status': 'error', 'reason': 'authentication_failed'}

        if len(slot_index_bytes) != 4:
            return {'status': 'error', 'reason': 'invalid_slot_format'}

        offset, valid = self._compute_slot_offset(slot_index_bytes)
        if not valid:
            return {'status': 'error', 'reason': 'slot_out_of_range'}

        # Read length header
        length = struct.unpack('>I', self.buffer[offset:offset+4])[0]
        if length == 0 or length > 200:
            return {'status': 'error', 'reason': 'empty_or_corrupt_slot'}

        # Read MAC and payload
        mac = bytes(self.buffer[offset+4:offset+20])
        payload = bytes(self.buffer[offset+20:offset+20+length])

        # Verify integrity
        expected_mac = hmac.new(
            SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode(),
            payload, hashlib.sha256).digest()[:16]

        if not hmac.compare_digest(mac, expected_mac):
            return {'status': 'error', 'reason': 'integrity_check_failed'}

        return {'status': 'ok', 'payload': payload}

    def get_queue_stats(self) -> Dict:
        """Return non-sensitive queue statistics."""
        active_slots = sum(1 for m in self.slot_metadata if m is not None)
        return {
            'active_slots': active_slots,
            'total_writes': self.write_count,
            'buffer_utilization': active_slots / MAX_SLOTS
        }
